	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CommandInvocation
	 */
		public CommandInvocation createCommandInvocation( CreateCommandInvocationCommand command ) {

		CommandInvocation entity = new CommandInvocation();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCommandInvocationId( command.getCommandInvocationId() );
            entity.setInvocationId( command.getInvocationId() );
            entity.setRequestedAt( command.getRequestedAt() );
            entity.setCompletedAt( command.getCompletedAt() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CommandInvocation {0} ", entity.toString() );

		return entity;
	}

