            entity.setInvocationId( command.getInvocationId() );
            entity.setRequestedAt( command.getRequestedAt() );
            entity.setCompletedAt( command.getCompletedAt() );
            entity.setDevice( command.getDevice() );
            entity.setCommandDefinition( command.getCommandDefinition() );
            entity.setActuator( command.getActuator() );
            entity.setUser( command.getUser() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
